     1→import { useCallback, useMemo } from "react";
     2→import { invoke } from "@tauri-apps/api/core";
     3→import { getTabViewModel, useTabStore } from "@/stores/tab-store";
     4→import type { TabNavigationState, TabViewModel } from "@/stores/tab-store";
     5→import type { IconData } from "@/components/ui/icon-picker";
     6→import { buildColdStartBreadcrumb } from "@/navigation/navigate";
     7→import type { BreadcrumbStackItem } from "@/navigation/breadcrumb-builder";
     8→import {
     9→  normalizeSettingsSection,
    10→  normalizeWorkspaceSection,
    11→} from "@/navigation/navigation-meta";
    12→import { registry } from "@/navigation/route-registry";
    13→import { useLocalWorkspaces } from "@/hooks/use-workspaces";
    14→import type { PageConfig } from "@/hooks/use-pages";
    15→
    16→// ─── Hook 1: useTabList ─────────────────────────────────────────────────────
    17→// Returns the tab view model list. Only re-renders when the tabs array changes.
    18→
    19→export function useTabList(): TabViewModel[] {
    20→  const rawTabs = useTabStore((state) => state.tabs);
    21→  return useMemo(() => rawTabs.map(getTabViewModel), [rawTabs]);
    22→}
    23→
    24→// ─── Hook 2: useActiveTabState ──────────────────────────────────────────────
    25→// Returns reactive state about the active tab. Re-renders when active tab changes.
    26→
    27→export interface ActiveTabState {
    28→  activeTabId: string | null;
    29→  activeTab: TabViewModel | null;
    30→  canGoBack: boolean;
    31→  canGoForward: boolean;
    32→  currentUrl: string | null;
    33→  currentNavigationState: TabNavigationState | null;
    34→}
    35→
    36→export function useActiveTabState(): ActiveTabState {
    37→  const activeTabId = useTabStore((state) => state.activeTabId);
    38→  const activeTabRaw = useTabStore((state) =>
    39→    state.tabs.find((tab) => tab.id === state.activeTabId) ?? null
    40→  );
    41→  const canGoBackFn = useTabStore((state) => state.canGoBack);
    42→  const canGoForwardFn = useTabStore((state) => state.canGoForward);
    43→  const getCurrentUrl = useTabStore((state) => state.getCurrentUrl);
    44→  const getCurrentNavigationState = useTabStore(
    45→    (state) => state.getCurrentNavigationState
    46→  );
    47→
    48→  const activeTab = useMemo(
    49→    () => (activeTabRaw ? getTabViewModel(activeTabRaw) : null),
    50→    [activeTabRaw]
    51→  );
    52→
    53→  const canGoBack = activeTabId ? canGoBackFn(activeTabId) : false;
    54→  const canGoForward = activeTabId ? canGoForwardFn(activeTabId) : false;
    55→  const currentUrl = activeTabId ? getCurrentUrl(activeTabId) : null;
    56→  const currentNavigationState = activeTabId
    57→    ? getCurrentNavigationState(activeTabId)
    58→    : null;
    59→
    60→  return useMemo(
    61→    () => ({
    62→      activeTabId,
    63→      activeTab,
    64→      canGoBack,
    65→      canGoForward,
    66→      currentUrl,
    67→      currentNavigationState,
    68→    }),
    69→    [activeTabId, activeTab, canGoBack, canGoForward, currentUrl, currentNavigationState]
    70→  );
    71→}
    72→
    73→// ─── Hook 3: useTabActions ──────────────────────────────────────────────────
    74→// Returns stable action functions for tab operations. These reference Zustand
    75→// store actions + resolve navigation logic. Actions that depend on activeTabId
    76→// will have their identity change when activeTabId changes.
    77→
    78→export interface TabActions {
    79→  openUrl: (
    80→    url: string,
    81→    options?: { breadcrumbStack?: BreadcrumbStackItem[]; openInNewTab?: boolean }
    82→  ) => string;
    83→  replaceUrl: (
    84→    url: string,
    85→    patch?: Partial<TabNavigationState>
    86→  ) => string | undefined;
    87→  pushUrl: (
    88→    url: string,
    89→    patch?: Partial<TabNavigationState>
    90→  ) => string | undefined;
    91→  pushPage: (
    92→    item: BreadcrumbStackItem,
    93→    url: string
    94→  ) => string | undefined;
    95→  popTo: (index: number) => void;
    96→  resetStack: (next: TabNavigationState) => string | undefined;
    97→  navigateTo: (
    98→    url: string,
    99→    input: { label: string; icon?: IconData; descriptorId?: string; meta?: BreadcrumbStackItem["meta"] }
   100→  ) => string | undefined;
   101→  openPageTab: (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) => string;
   102→  openPageInNewTab: (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) => string;
   103→  openWorkspaceView: (workspaceId: string, viewPath: string, viewName: string, icon: IconData) => string;
   104→  openGlobalView: (path: string, name: string, icon: IconData) => string;
   105→  openWebUrl: (url: string, title?: string, workspaceId?: string) => string;
   106→  openChatTab: (chatId: string, chatName: string, workspaceId: string) => string;
   107→  switchToTab: (tabId: string) => string | null;
   108→  closeTab: (tabId: string) => void;
   109→  detachTabToNewWindow: (tabId: string) => Promise<boolean>;
   110→  getTabLink: (tabId: string) => string | null;
   111→}
   112→
   113→export function useTabActions(): TabActions {
   114→  const { getWorkspace } = useLocalWorkspaces();
   115→  const activeTabId = useTabStore((state) => state.activeTabId);
   116→  const rawTabs = useTabStore((state) => state.tabs);
   117→
   118→  const openTab = useTabStore((state) => state.openTab);
   119→  const closeTabStore = useTabStore((state) => state.closeTab);
   120→  const setActiveTab = useTabStore((state) => state.setActiveTab);
   121→  const replaceLocationStore = useTabStore((state) => state.replaceLocation);
   122→  const pushLocationStore = useTabStore((state) => state.pushLocation);
   123→  const getCurrentUrl = useTabStore((state) => state.getCurrentUrl);
   124→  const getCurrentNavigationState = useTabStore(
   125→    (state) => state.getCurrentNavigationState
   126→  );
   127→
   128→  const openUrl = useCallback(
   129→    (
   130→      url: string,
   131→      options?: {
   132→        breadcrumbStack?: BreadcrumbStackItem[];
   133→        openInNewTab?: boolean;
   134→      }
   135→    ) => {
   136→      const breadcrumbStack =
   137→        options?.breadcrumbStack?.length
   138→          ? options.breadcrumbStack
   139→          : buildColdStartBreadcrumb(url);
   140→
   141→      const navigationState: TabNavigationState = {
   142→        url,
   143→        breadcrumbStack,
   144→      };
   145→
   146→      if (options?.openInNewTab || !activeTabId) {
   147→        return openTab({
   148→          navigationState,
   149→          pinned: false,
   150→        });
   151→      }
   152→
   153→      replaceLocationStore(activeTabId, navigationState);
   154→      return activeTabId;
   155→    },
   156→    [activeTabId, openTab, replaceLocationStore]
   157→  );
   158→
   159→  const replaceUrl = useCallback(
   160→    (
   161→      url: string,
   162→      patch?: Partial<TabNavigationState>
   163→    ) => {
   164→      if (!activeTabId) {
   165→        return openUrl(url, {
   166→          breadcrumbStack: patch?.breadcrumbStack,
   167→          openInNewTab: true,
   168→        });
   169→      }
   170→
   171→      const breadcrumbStack =
   172→        patch?.breadcrumbStack?.length
   173→          ? patch.breadcrumbStack
   174→          : buildColdStartBreadcrumb(url);
   175→
   176→      replaceLocationStore(activeTabId, {
   177→        url,
   178→        breadcrumbStack,
   179→        activeIndexPath: patch?.activeIndexPath,
   180→        activeNodeId: patch?.activeNodeId,
   181→      });
   182→      return activeTabId;
   183→    },
   184→    [activeTabId, openUrl, replaceLocationStore]
   185→  );
   186→
   187→  const pushUrl = useCallback(
   188→    (
   189→      url: string,
   190→      patch?: Partial<TabNavigationState>
   191→    ) => {
   192→      if (!activeTabId) {
   193→        return openUrl(url, {
   194→          breadcrumbStack: patch?.breadcrumbStack,
   195→          openInNewTab: true,
   196→        });
   197→      }
   198→
   199→      const breadcrumbStack =
   200→        patch?.breadcrumbStack?.length
   201→          ? patch.breadcrumbStack
   202→          : buildColdStartBreadcrumb(url);
   203→
   204→      pushLocationStore(activeTabId, {
   205→        url,
   206→        breadcrumbStack,
   207→        activeIndexPath: patch?.activeIndexPath,
   208→        activeNodeId: patch?.activeNodeId,
   209→      });
   210→      return activeTabId;
   211→    },
   212→    [activeTabId, openUrl, pushLocationStore]
   213→  );
   214→
   215→  const pushPage = useCallback(
   216→    (
   217→      item: BreadcrumbStackItem,
   218→      url: string
   219→    ) => {
   220→      if (!activeTabId) {
   221→        const stack = buildColdStartBreadcrumb(url);
   222→        return openUrl(url, {
   223→          breadcrumbStack: [...stack, item],
   224→          openInNewTab: true,
   225→        });
   226→      }
   227→
   228→      // Push: append item to current breadcrumb stack
   229→      const currentState = getCurrentNavigationState(activeTabId);
   230→      const currentStack = currentState?.breadcrumbStack ?? [];
   231→      pushLocationStore(activeTabId, {
   232→        url,
   233→        breadcrumbStack: [...currentStack, item],
   234→      });
   235→      return activeTabId;
   236→    },
   237→    [activeTabId, getCurrentNavigationState, openUrl, pushLocationStore]
   238→  );
   239→
   240→  const popTo = useCallback(
   241→    (index: number) => {
   242→      if (!activeTabId) return;
   243→      const currentState = getCurrentNavigationState(activeTabId);
   244→      if (!currentState) return;
   245→
   246→      const targetItem = currentState.breadcrumbStack[index];
   247→      if (!targetItem?.href) return;
   248→
   249→      // Navigate to the breadcrumb target URL with truncated stack
   250→      replaceLocationStore(activeTabId, {
   251→        url: targetItem.href,
   252→        breadcrumbStack: currentState.breadcrumbStack.slice(0, index + 1),
   253→      });
   254→    },
   255→    [activeTabId, getCurrentNavigationState, replaceLocationStore]
   256→  );
   257→
   258→  const resetStack = useCallback(
   259→    (next: TabNavigationState) => {
   260→      if (!activeTabId) {
   261→        return openUrl(next.url, {
   262→          breadcrumbStack: next.breadcrumbStack,
   263→          openInNewTab: true,
   264→        });
   265→      }
   266→
   267→      replaceLocationStore(activeTabId, next);
   268→      return activeTabId;
   269→    },
   270→    [activeTabId, openUrl, replaceLocationStore]
   271→  );
   272→
   273→  const navigateTo = useCallback(
   274→    (url: string, input: { label: string; icon?: IconData; descriptorId?: string; meta?: BreadcrumbStackItem["meta"] }) => {
   275→      const isExternal = url.startsWith("http://") || url.startsWith("https://");
   276→      if (isExternal) {
   277→        const workspaceId = input.meta?.workspaceId ?? "global";
   278→        const params = new URLSearchParams({ url, title: input.label });
   279→        const webUrl = `/workspace/${encodeURIComponent(workspaceId)}/web?${params.toString()}`;
   280→        return openUrl(webUrl);
   281→      }
   282→
   283→      // Use URL-based navigation directly
   284→      const stack = buildColdStartBreadcrumb(url, {
   285→        label: input.label,
   286→        icon: input.icon,
   287→      });
   288→
   289→      if (activeTabId) {
   290→        replaceLocationStore(activeTabId, {
   291→          url,
   292→          breadcrumbStack: stack,
   293→        });
   294→        return activeTabId;
   295→      }
   296→
   297→      return openTab({
   298→        pinned: false,
   299→        navigationState: {
   300→          url,
   301→          breadcrumbStack: stack,
   302→        },
   303→      });
   304→    },
   305→    [activeTabId, openUrl, openTab, replaceLocationStore]
   306→  );
   307→
   308→  const openPageTab = useCallback(
   309→    (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) => {
   310→      const url = registry.build("/workspace/:workspaceId/pages/:pageSlug+", {
   311→        workspaceId,
   312→        pageSlug: page.slug,
   313→      });
   314→      return openUrl(url, { breadcrumbStack });
   315→    },
   316→    [openUrl]
   317→  );
   318→
   319→  const openPageInNewTab = useCallback(
   320→    (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) => {
   321→      const url = registry.build("/workspace/:workspaceId/pages/:pageSlug+", {
   322→        workspaceId,
   323→        pageSlug: page.slug,
   324→      });
   325→      return openUrl(url, { openInNewTab: true, breadcrumbStack });
   326→    },
   327→    [openUrl]
   328→  );
   329→
   330→  const openWorkspaceView = useCallback(
   331→    (workspaceId: string, viewPath: string, _viewName: string, _icon: IconData) => {
   332→      if (!viewPath) {
   333→        const url = registry.build("/workspace/:workspaceId", { workspaceId });
   334→        return openUrl(url);
   335→      }
   336→      const section = normalizeWorkspaceSection(viewPath);
   337→      const url = registry.build(`/workspace/:workspaceId/${section}`, { workspaceId });
   338→      return openUrl(url);
   339→    },
   340→    [openUrl]
   341→  );
   342→
   343→  const openGlobalView = useCallback(
   344→    (path: string, _name: string, _icon: IconData) => {
   345→      return openUrl(path);
   346→    },
   347→    [openUrl]
   348→  );
   349→
   350→  const openWebUrl = useCallback(
   351→    (url: string, title?: string, workspaceId?: string) => {
   352→      // Derive workspaceId from current tab URL via registry match
   353→      const currentTabUrl = activeTabId ? getCurrentUrl(activeTabId) : null;
   354→      const routeMatch = currentTabUrl ? registry.match(currentTabUrl) : null;
   355→      const wsId =
   356→        workspaceId ??
   357→        routeMatch?.params.workspaceId ??
   358→        "global";
   359→      const params = new URLSearchParams({
   360→        url,
   361→        title: title ?? safeHostname(url),
   362→      });
   363→      const webUrl = `/workspace/${encodeURIComponent(wsId)}/web?${params.toString()}`;
   364→      return openUrl(webUrl);
   365→    },
   366→    [activeTabId, getCurrentUrl, openUrl]
   367→  );
   368→
   369→  const openChatTab = useCallback(
   370→    (_chatId: string, _chatName: string, workspaceId: string) => {
   371→      const url = registry.build("/workspace/:workspaceId/chat", { workspaceId });
   372→      return openUrl(url);
   373→    },
   374→    [openUrl]
   375→  );
   376→
   377→  const switchToTab = useCallback(
   378→    (tabId: string) => {
   379→      setActiveTab(tabId);
   380→      return getCurrentUrl(tabId);
   381→    },
   382→    [getCurrentUrl, setActiveTab]
   383→  );
   384→
   385→  const closeTab = useCallback(
   386→    (tabId: string) => {
   387→      closeTabStore(tabId);
   388→    },
   389→    [closeTabStore]
   390→  );
   391→
   392→  const getTabLink = useCallback(
   393→    (tabId: string) => {
   394→      const state = getCurrentNavigationState(tabId);
   395→      return state?.url ?? null;
   396→    },
   397→    [getCurrentNavigationState]
   398→  );
   399→
   400→  const detachTabToNewWindow = useCallback(
   401→    async (tabId: string) => {
   402→      const tab = rawTabs.find((item) => item.id === tabId);
   403→      const state = getCurrentNavigationState(tabId);
   404→      const tabView = tab ? getTabViewModel(tab) : null;
   405→
   406→      if (!tab || !state) {
   407→        return false;
   408→      }
   409→
   410→      // Use registry match to extract route info from the URL
   411→      const match = registry.match(state.url);
   412→      const workspaceId = match?.params.workspaceId;
   413→      if (!workspaceId) {
   414→        return false;
   415→      }
   416→
   417→      const pageSlug = match?.params.pageSlug;
   418→      const isPageRoute = match?.pattern === "/workspace/:workspaceId/page/:pageSlug+";
   419→
   420→      if (isPageRoute && pageSlug) {
   421→        const workspace = getWorkspace(workspaceId);
   422→        if (!workspace?.path) {
   423→          return false;
   424→        }
   425→
   426→        await invoke("open_workspace_page_preview_window", {
   427→          workspaceId,
   428→          workspacePath: workspace.path,
   429→          slug: pageSlug,
   430→          title: tabView?.label ?? pageSlug,
   431→          view: tab.viewMode ?? "page",
   432→        });
   433→        closeTabStore(tabId);
   434→        return true;
   435→      }
   436→
   437→      await invoke("open_workspace_in_new_window", {
   438→        workspaceId,
   439→        routePath: state.url,
   440→        title: tabView?.label ?? state.url,
   441→      });
   442→      closeTabStore(tabId);
   443→      return true;
   444→    },
   445→    [closeTabStore, getCurrentNavigationState, getWorkspace, rawTabs]
   446→  );
   447→
   448→  return useMemo(
   449→    () => ({
   450→      openUrl,
   451→      replaceUrl,
   452→      pushUrl,
   453→      pushPage,
   454→      popTo,
   455→      resetStack,
   456→      navigateTo,
   457→      openPageTab,
   458→      openPageInNewTab,
   459→      openWorkspaceView,
   460→      openGlobalView,
   461→      openWebUrl,
   462→      openChatTab,
   463→      switchToTab,
   464→      closeTab,
   465→      detachTabToNewWindow,
   466→      getTabLink,
   467→    }),
   468→    [
   469→      openUrl,
   470→      replaceUrl,
   471→      pushUrl,
   472→      pushPage,
   473→      popTo,
   474→      resetStack,
   475→      navigateTo,
   476→      openPageTab,
   477→      openPageInNewTab,
   478→      openWorkspaceView,
   479→      openGlobalView,
   480→      openWebUrl,
   481→      openChatTab,
   482→      switchToTab,
   483→      closeTab,
   484→      detachTabToNewWindow,
   485→      getTabLink,
   486→    ]
   487→  );
   488→}
   489→
   490→// ─── Hook 4: useTabNavigation ───────────────────────────────────────────────
   491→// Returns navigation actions bound to the active tab (history back/forward/jump).
   492→
   493→export interface TabNavigationActions {
   494→  goBackInTab: () => void;
   495→  goForwardInTab: () => void;
   496→  jumpToHistory: (historyIndex: number) => void;
   497→  navigateInTab: (url: string) => void;
   498→}
   499→
   500→export function useTabNavigation(): TabNavigationActions {
   501→  const activeTabId = useTabStore((state) => state.activeTabId);
   502→  const navigate = useTabStore((state) => state.navigate);
   503→  const goBack = useTabStore((state) => state.goBack);
   504→  const goForward = useTabStore((state) => state.goForward);
   505→  const canGoBackFn = useTabStore((state) => state.canGoBack);
   506→  const canGoForwardFn = useTabStore((state) => state.canGoForward);
   507→  const jumpToHistoryStore = useTabStore((state) => state.jumpToHistory);
   508→
   509→  const goBackInTab = useCallback(() => {
   510→    if (activeTabId && canGoBackFn(activeTabId)) {
   511→      goBack(activeTabId);
   512→    }
   513→  }, [activeTabId, canGoBackFn, goBack]);
   514→
   515→  const goForwardInTab = useCallback(() => {
   516→    if (activeTabId && canGoForwardFn(activeTabId)) {
   517→      goForward(activeTabId);
   518→    }
   519→  }, [activeTabId, canGoForwardFn, goForward]);
   520→
   521→  const jumpToHistory = useCallback(
   522→    (historyIndex: number) => {
   523→      if (!activeTabId) return;
   524→      jumpToHistoryStore(activeTabId, historyIndex);
   525→    },
   526→    [activeTabId, jumpToHistoryStore]
   527→  );
   528→
   529→  const navigateInTab = useCallback(
   530→    (url: string) => {
   531→      if (!activeTabId) return;
   532→      navigate(activeTabId, url);
   533→    },
   534→    [activeTabId, navigate]
   535→  );
   536→
   537→  return useMemo(
   538→    () => ({ goBackInTab, goForwardInTab, jumpToHistory, navigateInTab }),
   539→    [goBackInTab, goForwardInTab, jumpToHistory, navigateInTab]
   540→  );
   541→}
   542→
   543→// ─── Composed hook: usePageTabs (backward-compatible) ───────────────────────
   544→// Composes the 4 granular hooks. Existing consumers can continue using this
   545→// without changes, but new code should prefer the granular hooks.
   546→
   547→export function usePageTabs() {
   548→  const tabs = useTabList();
   549→  const activeState = useActiveTabState();
   550→  const actions = useTabActions();
   551→  const navigation = useTabNavigation();
   552→
   553→  return useMemo(
   554→    () => ({
   555→      tabs,
   556→      ...activeState,
   557→      ...actions,
   558→      ...navigation,
   559→    }),
   560→    [tabs, activeState, actions, navigation]
   561→  );
   562→}
   563→
   564→// ─── Utilities ──────────────────────────────────────────────────────────────
   565→
   566→function safeHostname(url: string): string {
   567→  try {
   568→    return new URL(url).hostname;
   569→  } catch {
   570→    return url;
   571→  }
   572→}
