   109→        setShouldReserveMacOSControlsSpace(false);
   110→      }
   111→    };
   112→    detectPlatform();
   113→
   114→    return () => {
   115→      mounted = false;
   116→      if (unlisten) {
   117→        unlisten();
   118→      }
   119→    };
   120→  }, []);
   121→
   122→  // Get tab data from granular hooks
